'use strict';
const planets=[
 {name:'Mercury',cn:'水星',image:'水星',fact:'Mercury is small.',translation:'水星个头小。',page:9},
 {name:'Venus',cn:'金星',image:'金星',fact:'Venus is hot.',translation:'金星很热。',page:15},
 {name:'Earth',cn:'地球',image:'地球',fact:'Earth is our home.',translation:'地球是我们的家。',page:21},
 {name:'Mars',cn:'火星',image:'火星',fact:'Mars is red.',translation:'火星看起来红红的。',page:28},
 {name:'Jupiter',cn:'木星',image:'木星',fact:'Jupiter is big.',translation:'木星个头大。',page:35},
 {name:'Saturn',cn:'土星',image:'土星',fact:'Saturn has rings.',translation:'土星有光环。',page:42},
 {name:'Uranus',cn:'天王星',image:'天王星',fact:'Uranus spins on its side.',translation:'天王星像侧躺着一样自转。',page:48},
 {name:'Neptune',cn:'海王星',image:'海王星',fact:'Neptune is far away.',translation:'海王星很遥远。',page:54},
 {name:'Sun',cn:'太阳',image:'太阳',fact:'The Sun is a star.',translation:'太阳是一颗恒星。',page:3}
];
const $=s=>document.querySelector(s),audio=$('#english-audio'),content=$('#content');let mode='overview',lesson=0,showChinese=true,round=0,targets=[],choices=[],answered=false,orderCount=0,bank=[],feedbackTimer,playingButton=null;
function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function feedback(s){$('#feedback').textContent=s;$('#feedback').hidden=false;clearTimeout(feedbackTimer);feedbackTimer=setTimeout(()=>$('#feedback').hidden=true,2500)}
function stopAudio(){audio.pause();audio.onended=null;if(playingButton)playingButton.classList.remove('playing');playingButton=null}
async function speak(id,button){stopAudio();audio.src='english-audio/'+id+'.mp3';playingButton=button||null;if(button)button.classList.add('playing');audio.onended=()=>{if(playingButton)playingButton.classList.remove('playing')};try{await audio.play()}catch{feedback('声音暂时没能播放，点一下再试试。')}}
audio.onerror=()=>feedback('音频未能加载，请检查网络后重试。');
function image(p){return 'planets/'+p.image+'.webp'}
function sentence(i){return i===8?'This is the Sun.':'This is '+planets[i].name+'.'}
function cnSentence(i){return i===8?'这是太阳。':'这是'+planets[i].cn+'。'}
function route(next,idx=0){stopAudio();mode=next;document.body.classList.toggle('lesson-active',mode==='lesson');lesson=Math.max(0,Math.min(8,Number(idx)||0));document.querySelectorAll('[data-mode]').forEach(b=>{if(b.dataset.mode===mode)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});history.replaceState(null,'',mode==='lesson'?'#lesson='+lesson:'#'+mode);render();scrollTo({top:0,behavior:'instant'})}
function render(){if(mode==='overview')overview();else if(mode==='lesson')single();else if(mode==='find')find();else ordering();}
function overview(){content.innerHTML='<h1>和星球说声 Hello!</h1><p class="sub">点星球听名字，再去学一句英文。</p><div class="planet-grid"></div>';const grid=$('.planet-grid');for(let i=0;i<8;i++){const p=planets[i],card=document.createElement('article');card.className='planet-card';card.innerHTML=`<button class="image-word" aria-label="听 ${p.name}"><img src="${image(p)}" alt="${p.cn}" draggable="false"></button><strong lang="en">${p.name}</strong><span class="cn">${p.cn}</span><button class="word-button" lang="en">♪ ${p.name}</button><a class="learn-link" href="#lesson=${i}">学一句英文 →</a>`;card.querySelector('.image-word').onclick=e=>speak('word-'+i,e.currentTarget);card.querySelector('.word-button').onclick=e=>speak('word-'+i,e.currentTarget);card.querySelector('a').onclick=e=>{e.preventDefault();route('lesson',i)};grid.append(card)}const sun=document.createElement('button');sun.className='sun-banner';sun.innerHTML=`<img src="${image(planets[8])}" alt="太阳"><div><strong lang="en">Sun</strong><span>再认识一位朋友：太阳，是恒星。</span></div><span class="arrow">→</span>`;sun.onclick=()=>route('lesson',8);content.append(sun)}
function single(){const p=planets[lesson];content.innerHTML=`<section class="lesson-layout"><button class="image-word hero-button" aria-label="听 ${p.name}"><img class="planet-hero" src="${image(p)}" alt="${p.cn}"></button><div><h1 class="lesson-title" lang="en">${p.name}</h1><p class="lesson-cn cn">${p.cn}</p><button class="word-button listen-word" id="word">♪ 听单词，再跟着说</button><div class="sentence"><button id="sentence" aria-label="听句子 ${sentence(lesson)}">♪</button><div><strong lang="en">${sentence(lesson)}</strong><small class="cn">${cnSentence(lesson)}</small></div></div><div class="sentence"><button id="fact" aria-label="听句子 ${p.fact}">♪</button><div><strong lang="en">${p.fact}</strong><small class="cn">${p.translation}</small></div></div>${lesson===8?'<p class="sun-note">太阳是恒星，不属于八大行星。影像经过赋色。</p>':''}</div></section><div class="lesson-nav"><button id="prev-lesson" ${lesson===0?'disabled':''}>‹ 上一颗</button><a href="index.html#page=${p.page}">去看中文科普 ↗</a><button id="next-lesson" ${lesson===8?'disabled':''}>下一颗 ›</button></div>`;$('.hero-button').onclick=e=>speak('word-'+lesson,e.currentTarget);$('#word').onclick=e=>speak('word-'+lesson,e.currentTarget);$('#sentence').onclick=e=>speak('sentence-'+lesson,e.currentTarget);$('#fact').onclick=e=>speak('fact-'+lesson,e.currentTarget);$('#prev-lesson').onclick=()=>route('lesson',lesson-1);$('#next-lesson').onclick=()=>route('lesson',lesson+1)}
function initFind(){round=0;targets=shuffle([0,1,2,3,4,5,6,7]);answered=false;makeChoices()}
function makeChoices(){const target=targets[round];choices=shuffle([target,...shuffle([0,1,2,3,4,5,6,7].filter(x=>x!==target)).slice(0,2)]);answered=false}
function find(){if(!targets.length)initFind();if(round>=8){content.innerHTML='<h1>八位星球伙伴，都找到了！</h1><p class="sub">再听一听，你还记得它们的名字吗？</p><button class="primary" id="again">再玩一次</button>';$('#again').onclick=()=>{initFind();render()};return}content.innerHTML=`<div class="game-top"><div><h1>听一听，找星球</h1><p class="sub">先听英语，再点一张图片。</p></div><button id="question" class="primary">♪ 听题目</button></div><div class="rounds">${targets.map((_,i)=>'<span class="'+(i<round?'complete':'')+'"></span>').join('')}</div><div class="choices"></div><p class="result" role="status">点“听题目”，开始找一找。</p><div class="game-actions"><button id="next-question" class="primary" hidden>下一题 →</button><button id="restart-find" class="secondary">重新开始</button></div>`;$('#question').onclick=e=>{speak('find-'+targets[round],e.currentTarget);$('.result').textContent='听到了吗？点一张星球图片。'};for(const i of choices){const b=document.createElement('button');b.className='choice';b.setAttribute('aria-label','选择'+planets[i].cn);b.innerHTML=`<img src="${image(planets[i])}" alt="${planets[i].cn}"><small>点我选这一颗</small>`;b.onclick=()=>{if(answered)return;if(i===targets[round]){answered=true;b.classList.add('correct');$('.result').textContent='Yes! '+planets[i].name+'!';speak('yes',b);$('#next-question').hidden=false;$('#next-question').textContent=round===7?'完成啦 →':'下一题 →'}else{b.classList.add('try');$('.result').textContent='Try again. 再听一遍试试。';speak('retry',b);setTimeout(()=>b.classList.remove('try'),900)}};$('.choices').append(b)}$('#next-question').onclick=()=>{round++;if(round<8)makeChoices();find();if(round===8)speak('done')};$('#restart-find').onclick=()=>{initFind();find()}}
function ordering(){if(!bank.length)bank=shuffle([0,1,2,3,4,5,6,7]);content.innerHTML='<div class="game-top"><div><h1>从太阳向外，排一排</h1><p class="sub">点下面的星球，把它送到自己的位置。</p></div><button id="order-prompt" class="primary">♪ 听提示</button></div><div class="order-track"></div><p class="result" role="status"></p><div class="order-bank"></div><div class="game-actions" style="margin-top:24px"><button id="restart-order" class="secondary">重新排一排</button></div>';for(let i=0;i<8;i++){const slot=document.createElement('div');slot.className='order-slot';slot.setAttribute('aria-label','第'+(i+1)+'个位置');slot.innerHTML=i<orderCount?`<img src="${image(planets[i])}" alt="${planets[i].cn}"><small lang="en">${planets[i].name}</small>`:String(i+1);$('.order-track').append(slot)}$('.result').textContent=orderCount===8?'You did it! 八颗行星排好啦！':orderCount===0?'先找 Mercury，再一路向外。':'下一位是谁呢？';for(const i of bank){const b=document.createElement('button');b.disabled=i<orderCount;b.innerHTML=`<img src="${image(planets[i])}" alt="${planets[i].cn}"><strong lang="en">${planets[i].name}</strong><small class="cn">${planets[i].cn}</small>`;b.onclick=()=>{if(i===orderCount){orderCount++;ordering();speak(orderCount===8?'done':'word-'+i)}else{feedback('再想想，也可以点“听提示”。');speak('retry',b)}};$('.order-bank').append(b)}$('#order-prompt').onclick=e=>speak(orderCount===8?'done':orderCount===0?'start':'find-'+orderCount,e.currentTarget);$('#restart-order').onclick=()=>{orderCount=0;bank=shuffle(bank);ordering()}}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>route(b.dataset.mode,lesson));$('#chinese-toggle').onclick=()=>{showChinese=!showChinese;document.body.classList.toggle('hide-chinese',!showChinese);$('#chinese-toggle').setAttribute('aria-pressed',showChinese);$('#chinese-toggle').textContent='中文 '+(showChinese?'开':'关');try{localStorage.setItem('planet-english-chinese',String(showChinese))}catch{}};try{showChinese=localStorage.getItem('planet-english-chinese')!=='false';if(!showChinese){document.body.classList.add('hide-chinese');$('#chinese-toggle').textContent='中文 关';$('#chinese-toggle').setAttribute('aria-pressed',false)}const saved=Number(localStorage.getItem('astronaut-page'));if(saved>=1&&saved<=60)$('#back-book').href='index.html#page='+saved}catch{}const match=location.hash.match(/lesson=(\d+)/);route(match?'lesson':['find','order'].includes(location.hash.slice(1))?location.hash.slice(1):'overview',match?Number(match[1]):0);window.addEventListener('pagehide',stopAudio);
